alter table public.companies add column portal_cancellation_hours integer not null default 24 check(portal_cancellation_hours between 0 and 720),add column portal_reschedule_hours integer not null default 12 check(portal_reschedule_hours between 0 and 720);
create table public.appointment_portal_actions(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),customer_id uuid not null references public.customers(id),appointment_id uuid not null references public.appointments(id),auth_user_id uuid not null,action text not null check(action in('cancelamento','reagendamento')),previous_scheduled_at timestamptz,new_scheduled_at timestamptz,reason text not null,created_at timestamptz not null default now());create index portal_actions_user_idx on public.appointment_portal_actions(auth_user_id,created_at desc);create index portal_actions_company_idx on public.appointment_portal_actions(company_id,created_at desc);create index portal_actions_customer_idx on public.appointment_portal_actions(customer_id);create index portal_actions_appointment_idx on public.appointment_portal_actions(appointment_id);
alter table public.appointment_portal_actions enable row level security;create policy portal_actions_select on public.appointment_portal_actions for select to authenticated using(auth_user_id=(select auth.uid())or(select private.is_company_member(company_id)));revoke all on public.appointment_portal_actions from public,anon,authenticated;grant select on public.appointment_portal_actions to authenticated;
create function private.portal_cancel_appointment(p_appointment uuid,p_reason text)returns void language plpgsql security definer set search_path=''as $$declare c public.customers;a public.appointments;co public.companies;begin c:=private.portal_customer();select*into a from public.appointments where id=p_appointment and customer_id=c.id and company_id=c.company_id for update;select*into co from public.companies where id=c.company_id;if not found or a.status not in('agendado','confirmado','pendente')or a.scheduled_at<=now()+make_interval(hours=>co.portal_cancellation_hours)or length(trim(p_reason))<3 then raise exception'Cancelamento fora das regras';end if;update public.appointments set status='cancelado',cancellation_reason='Cancelado pelo portal: '||trim(p_reason)where id=a.id;insert into public.appointment_portal_actions(company_id,customer_id,appointment_id,auth_user_id,action,previous_scheduled_at,reason)values(c.company_id,c.id,a.id,(select auth.uid()),'cancelamento',a.scheduled_at,trim(p_reason));end$$;
create function private.portal_reschedule_appointment(p_appointment uuid,p_slot timestamptz,p_reason text)returns void language plpgsql security definer set search_path=''as $$declare c public.customers;a public.appointments;co public.companies;s public.services;begin c:=private.portal_customer();select*into a from public.appointments where id=p_appointment and customer_id=c.id and company_id=c.company_id for update;select*into co from public.companies where id=c.company_id;select*into s from public.services where id=a.service_id;if a.id is null or a.status not in('agendado','confirmado','pendente')or a.scheduled_at<=now()+make_interval(hours=>co.portal_reschedule_hours)or p_slot<=now()or length(trim(p_reason))<3 then raise exception'Reagendamento fora das regras';end if;update public.appointments set scheduled_at=p_slot,notes=concat_ws(E'\n',notes,'Reagendado pelo portal: '||trim(p_reason))where id=a.id;insert into public.appointment_portal_actions(company_id,customer_id,appointment_id,auth_user_id,action,previous_scheduled_at,new_scheduled_at,reason)values(c.company_id,c.id,a.id,(select auth.uid()),'reagendamento',a.scheduled_at,p_slot,trim(p_reason));end$$;
create function public.cancel_portal_appointment(p_appointment uuid,p_reason text)returns void language sql security invoker set search_path=''as $$select private.portal_cancel_appointment(p_appointment,p_reason)$$;create function public.reschedule_portal_appointment(p_appointment uuid,p_slot timestamptz,p_reason text)returns void language sql security invoker set search_path=''as $$select private.portal_reschedule_appointment(p_appointment,p_slot,p_reason)$$;
revoke all on function private.portal_cancel_appointment(uuid,text),private.portal_reschedule_appointment(uuid,timestamptz,text)from public,anon;grant execute on function private.portal_cancel_appointment(uuid,text),private.portal_reschedule_appointment(uuid,timestamptz,text)to authenticated;revoke all on function public.cancel_portal_appointment(uuid,text),public.reschedule_portal_appointment(uuid,timestamptz,text)from public,anon;grant execute on function public.cancel_portal_appointment(uuid,text),public.reschedule_portal_appointment(uuid,timestamptz,text)to authenticated;create trigger audit_appointment_portal_actions after insert or update or delete on public.appointment_portal_actions for each row execute function private.capture_audit_log();
